package dev.steelwool.mixin.patch;

import java.util.Set;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.entity.BlockEntityType;
import org.spongepowered.asm.mixin.Final;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;

/**
 * Adds NeoForge's {@code BlockEntityType.getValidBlocks()}. NeoForge's extra constructors
 * ({@code (supplier, Block...)}, {@code (supplier, boolean, Block...)} and
 * {@code (supplier, Set, boolean)}) are generated by {@code SteelWoolMixinPlugin}; the "only op can
 * set NBT" flag they take is ignored.
 */
@Mixin(BlockEntityType.class)
public abstract class BlockEntityTypeMixin {
	@Shadow
	@Final
	private Set<Block> validBlocks;

	public Set<Block> getValidBlocks() {
		return validBlocks;
	}
}
